const e={title:"TripReel - אפליקציית אנימציית טיולים חינמית: הפוך תמונות לסרטונים יפים",description:"צור סרטוני טיולים מדהימים עם מפות מונפשות ומסלולי טיסה. אפליקציית אנימציית טיולים חינמית עם מיפוי מסלול גלוב 3D. הפוך את התמונות שלך לסרטוני מסע יפים באופן אוטומטי. פרטיות קודמת, עובד במצב לא מקוון.",keywords:"אפליקציית אנימציית טיולים, אפליקציית אנימציית מפת טיולים, אפליקציית אנימציית מסלול טיולים, אפליקציית אנימציית טיסה, יוצר סרטוני טיולים, סרטון טיולים אוטומטי, מפת טיולים מונפשת, אנימציית מסלול טיסה, אנימציית טיולים, אנימציית גלוב, סרטון סיכום טיולים, תמונה לסרטון, הדגשים של טיולים, אפליקציית טיולים חינמית, יוצר סרטונים לא מקוון, אפליקציית טיולים פרטית, סרטון גליל מצלמה"},t={logoAlt:"לוגו TripReel",appName:"TripReel",howItWorks:"איך זה עובד",video:"וידאו",features:"תכונות",theApp:"האפליקציה"},i={badge:"הפכו תמונות לסיפורי מסע",title1:"גלריית התמונות שלכם,",title2:"במלוא ההדר",description:"TripReel יוצר באופן אוטומטי סרטוני מסע מדהימים ממיקומי התמונות שלכם. צפו במסעות שלכם מתעוררים לחיים עם מפות מסלול מונפשות ונתיבי טיסה על גלובוס תלת-ממדי, כשהמידע שלכם נשאר פרטי ומאובטח.",secure:"100% מאובטח",worksOffline:"עובד במצב לא מקוון",globeAlt:"אנימציית גלובוס TripReel"},r={title:"איך זה עובד",subtitle:"שלושה שלבים פשוטים ליצירת סרטון המסע המושלם שלכם",step1:{title:"אפשרו גישה לתמונות",description:"העניקו ל-TripReel גישה לספריית התמונות שלכם. האפליקציה קוראת רק את מטא־הנתונים של המיקום, שום דבר אחר."},step2:{title:"זיהוי אוטומטי של טיולים",description:"TripReel מנתח את מטא־הנתונים של המיקום ומזהה בחכמה את הטיולים שלכם על בסיס תאריכים ומיקומים."},step3:{title:"צרו את הסרטון שלכם",description:"צפו במסע שלכם מתגלה על אנימציית גלובוס מדהימה, מוכן לשיתוף ברשתות החברתיות."}},o={title:"ראו את הקסם קורה",subtitle:"צפו איך TripReel הופך את ספריית התמונות שלכם לסרטוני מסע מדהימים",caption:"כך ייראה סרטון המסע הסופי שלכם"},s={title:"כל מה שאתם צריכים",subtitle:"תכונות עוצמתיות שתוכננו למטיילים מודרניים",twoTap:{title:"סרטוני מסע בשתי הקשות",description:"צרו סרטוני מסע מדהימים מספריית התמונות שלכם בשתי הקשות בלבד. ללא צורך בעריכה."},smartTrip:{title:"זיהוי חכם של טיולים",description:"מוצא ומקבץ באופן אוטומטי את הטיולים שלכם על ידי ניתוח תאריכים ומטא־נתונים של מיקום מהתמונות שלכם."},globe:{title:"אנימציית גלובוס מהממת",description:"צפו במסע שלכם מתעורר לחיים עם גלובוס תלת-ממדי מדהים המציג את מסלולי המסע המונפשים שלכם ונתיבי הטיסה ברחבי העולם."},privacy:{title:"פרטיות קודם כל",description:"הכל מעובד במכשיר שלכם. התמונות שלכם אף פעם לא עוזבות את הטלפון שלכם. עובד במצב טיסה."},customStyles:{title:"עיצובים מותאמים אישית",description:"בחרו ממגוון עיצובי גלובוס והתאמות אישיות כדי להתאים לאסתטיקה שלכם ולהפוך כל סרטון לייחודי."},manualControl:{title:"שליטה ידנית",description:"אתם יכולים להוסיף באופן ידני טיולים חדשים לגמרי אם שירותי המיקום לא היו מופעלים במכשיר שלכם."}},l={title:"רעיונות יצירתיים לסרטונים",subtitle:"קבלו השראה עם מה שאתם יכולים ליצור באמצעות TripReel. מבריחות סוף שבוע קצרות ועד הרפתקאות של שנה שלמה, צרו סרטוני מסע מדהימים לכל מסע.",description:"בין אם אתם יוצרים אנימציית מפת מסע, מתעדים נתיב טיסה או מכינים סיכום שנתי של טיולים, TripReel הופך את זה לקל להפוך את הזיכרונות שלכם לסרטונים לשיתוף.",ideas:{yearRecap:{title:"סיכום 2025",description:"צרו באופן אוטומטי את סרטון סיכום המסעות השנתי שלכם ל-2025"},europeRoadTrip:{title:"טיול כביש באירופה",description:"הציגו את ההרפתקה האירופית שלכם עם מפות מסלול מונפשות"},southeastAsia:{title:"מסע בדרום־מזרח אסיה",description:"הדמו את מסלול התרמילאות שלכם על פני מספר מדינות"},japanRail:{title:"מסע ברכבת ביפן",description:"צרו סרטוני מפה של מסלולי הרכבת שלכם ביפן"},crossCountry:{title:'חציית ארה"ב',description:"הפכו את הטיול הכביש האמריקאי שלכם לסרטון מסלול אפי"},islandHopping:{title:"דילוג בין איים",description:"הציגו את הטיולים שלכם מאי לאי עם אנימציות תלת-ממדיות מדהימות"},worldTour:{title:"מונטאז' סיור עולמי",description:"מספר טיולים לסרטון מסע גלובלי מדהים אחד"},travelPlans:{title:"תוכניות מסע 2026",description:"הדמו ותכננו את ההרפתקאות המסעיות המרגשות שלכם ל-2026"},lifetimeTravel:{title:"סיפור מסעות החיים",description:"צרו סרטון המציג את כל הטיולים שלכם לאורך החיים"},regionalExplorer:{title:"חוקר אזורי",description:"מפו את ההרפתקאות שלכם על פני מדינות, מחוזות ואזורים"},festivalCircuit:{title:"מעגל פסטיבלים",description:"מפו את המסע שלכם לפסטיבלי מוזיקה ואירועים"},bikeRoutes:{title:"בריחות העיר שלי",description:"הציגו את כל בריחות העיר שלכם"}}},a={title:"האפליקציה",subtitle:"זמינה כעת ב-App Store",alt1:"סרטוני מסע אוטומטיים - צרו סרטונים מדהימים בשניות",alt2:"זיהוי מיקום מתמונות - משתמש במטא-הנתונים של התמונות שלכם",alt3:"זיהוי טיולים - מקבץ באופן אוטומטי את המסעות שלכם",alt4:"סרטוני גלובוס מהממים - אנימציית גלובוס של המסע שלכם",alt5:"עיצובים מותאמים - התאימו אישית את סרטוני המסע שלכם"},n={comingSoon:"בקרוב",androidTitle:"אפליקציית Android בקרוב!",androidMessage:'גרסת Android עדיין לא זמינה אך תהיה בקרוב. שלחו לי הודעה ל-<a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> ואודיע לכם כשהיא תהיה מוכנה!',gotIt:"הבנתי!"},p={title:"שאלות נפוצות",subtitle:"כל מה שצריך לדעת על TripReel",q1:{question:"אני באמת יכול להשתמש באפליקציה באופן מלא במצב טיסה?",answer:"כן! למשתמשי פרימיום, האפליקציה יכולה לשמש באופן מלא במצב לא מקוון במצב טיסה ללא מגבלות. למשתמשים שאינם פרימיום, חלק מהתכונות נתמכות על ידי מודעות שעשויות לדרוש הפעלה זמנית של אינטרנט, אך למשתמשי פרימיום אין מודעות והאפליקציה ניתנת לשימוש מלא במצב טיסה."},q2:{question:"שדרגתי לפרימיום, איך אני יכול להסיר את סימן המים?",answer:"אנשים רבים שואלים איזו אפליקציה שימשה ליצירת הסרטונים האלה, לכן, לאחר השדרוג לפרימיום, יש לכם אפשרות להוסיף גרסה קטנה יותר של סימן המים (רק עם שם האפליקציה) או להסירו לגמרי אם תרצו."},q3:{question:"האם נתוני התמונות שלי בטוחים ופרטיים?",answer:"בהחלט! TripReel קורא רק מטא-נתונים של מיקום מהתמונות שלכם - אנחנו אף פעם לא ניגשים, לא מאחסנים או לא משדרים את תוכן התמונות בפועל. כל העיבוד מתבצע באופן מקומי במכשיר שלכם, ואף נתון לא עוזב את הטלפון שלכם. אתם יכולים לאמת זאת על ידי שימוש באפליקציה במצב טיסה - היא עובדת בצורה מושלמת במצב לא מקוון!"},q4:{question:"מה אם לתמונות שלי אין נתוני מיקום?",answer:"אין בעיה! אם שירותי המיקום לא היו מופעלים כשצילמתם את התמונות שלכם, אתם יכולים ליצור באופן ידני טיולים ולהוסיף מיקומים בעצמכם. האפליקציה נותנת לכם שליטה מלאה להתאמה אישית של ציר הזמן של המסעות שלכם."},q5:{question:"איך האפליקציה מזהה את הטיולים שלי באופן אוטומטי?",answer:"TripReel מנתח את מטא־הנתונים של המיקום וחותמות הזמן מהתמונות שלכם כדי לזהות בחכמה מתי ולאן נסעתם. היא מקבצת מיקומים ותאריכים סמוכים יחד כדי לזהות באופן אוטומטי את הטיולים שלכם ללא צורך בעבודה ידנית."},q6:{question:"אני יכול להתאים אישית את המראה של הסרטונים שלי?",answer:"כן! אתם יכולים לבחור ממגוון עיצובי גלובוס ולהתאים אישית היבטים שונים של סרטוני המסע המונפשים שלכם כדי להתאים לאסתטיקה האישית שלכם. משתמשי פרימיום מקבלים גישה לעיצובי אנימציית מסלול נוספים, ערכות נושא של מפות ואפשרויות נתיבי טיסה."},q7:{question:"אני צריך ליצור חשבון?",answer:"לא נדרש חשבון! TripReel עובד מיד לאחר ההורדה. אין רישום, אין התחברות ואין צורך במידע אישי. פשוט הורידו את האפליקציה והתחילו ליצור את סרטוני המסע שלכם מיד."},q8:{question:"למה חסר מיקום מהטיול שלי?",answer:"האפליקציה יכולה לעבוד רק עם נתונים זמינים, אז קודם כל אתם צריכים לפחות כמה תמונות במיקום הזה. שנית, אתם צריכים לוודא שהיו לכם נתוני מיקום מופעלים כשהייתם שם. שלישית, לפעמים קליטת GPS נמוכה עלולה לגרום לנתוני מיקום שגויים. אם שללתם את כל אלה והמיקום שלכם עדיין לא מופיע, אתם יכולים להוסיף באופן ידני את המיקום הזה מ-Trips Overview > כפתור Edit. אנא השתמשו גם ב-Contact לדיווח על הבעיה."},q9:{question:"איפה אני יכול לשתף את הסרטון המדהים שלי?",answer:"כמובן, אתם יכולים גם לשתף אותו בכל פלטפורמות המדיה החברתית. כדי להתאים טוב יותר לפלטפורמה, האפליקציה מאפשרת יחסי גובה-רוחב שונים לסרטונים שלכם."},q10:{question:"איפה אני יכול לדווח על באג?",answer:"פשוט פנו אליי ישירות ל-marian@qod.ee, והסבירו בקצרה מה הבעיה."}},d={title:"תמיכה בדוא״ל",description:'אם יש לכם משוב כלשהו או אתם נתקלים בבעיות, אנא אל תהססו לפנות אליי ישירות בדוא"ל הזה ואקרא ואטפל באופן אישי בבקשתכם במהירות האפשרית. תודה שאתם משתמשים באפליקציה!',close:"סגור"},c={default:{title:"🍪 עוגיות",message:"אנחנו משתמשים בעוגיות באתר TripReel כדי לשפר את החוויה שלכם. לא נאספים נתונים אישיים.",accept:"קבל",decline:"דחה",details:"פרטים"},theme:{title:"🍪 עוגיות",message:"🌙 כדי לשמור את העדפת הערכת הנושא שלכם, עליכם לקבל עוגיות חיוניות באתר TripReel. בלעדיהן, בחירת הנושא שלכם לא יכולה להישמר.",accept:"קבל",decline:"דחה",details:"פרטים"}},u={privacy:"מדיניות פרטיות האפליקציה",cookies:"מדיניות עוגיות האתר",contact:"יצירת קשר",cookiePreferences:"העדפות עוגיות",madeWith:"נוצר עם",forTravelers:"למטיילים ברחבי העולם",copyright:"© {{year}} TripReel."},T={title:"מוכנים לשתף את המסע שלכם?",description:"הורידו את TripReel היום והפכו את גלריית התמונות שלכם לסרטוני מסע מדהימים עם מפות ומסלולים מונפשים. ההרפתקאות שלכם ראויות לחגיגה.",features:"הורדה חינמית • מהיר ונוח • פרטיות מובטחת"},R={title:"אודות TripReel",subtitle:"יצרן סרטוני הדגשות טיול מקצועי ואפליקציית אנימציית מסלול מסע",howItWorks:{title:"כיצד פועלת אפליקציית סיכום הטיולים שלנו",description:"אפליקציית אנימציית הטיולים משתמשת באלגוריתמים חכמים לסריקת נתוני GPS מהתמונות שלך ולזיהוי הטיולים שלך באופן אוטומטי. אנימטור מסלול המסע יוצר אז אנימציות מסלול טיול חלקות וקולנועיות המציגות את נתיבך בערים, מדינות ויבשות. בין אם אתה יוצר סרטון הדגשות טיול מהיר לסוף שבוע או סרטון סיכום טיול לשנה שלמה, אפליקציית המפה המונפשת לטיולים הופכת זאת לפשוט."},customization:{title:"התאמה אישית נרחבת לסרטוני אנימציית הטיולים שלך",description:"אפליקציית יוצר סיפורי הטיולים מציעה אפשרויות התאמה ברמה מקצועית כדי להפוך את סרטוני מפת הטיולים המונפשים שלך לייחודיים באמת:",features:{videoQuality:"בחר בין 30 FPS, 60 FPS או 90 FPS פרימיום לאנימציות מסלול טיול חלקות כמשי בסרטוני הדגשות הטיול שלך",bitrate:"התאם את איכות הווידאו (bitrate) מרגיל לגבוה לסרטוני מסע מפה צלולים לחלוטין ללא ארטיפקטים ויזואליים",earthStyles:"בחר מתוך מספר סגנונות כדור ארץ מדהימים כולל מציאותי, אורות לילה, מפת יום ותצוגות לוויין לסרטוני מפת הטיולים המונפשים שלך",borders:"החלף גבולות מדינות באנימטור מסלול המסע שלך עם צבעים ועובי הניתנים להתאמה אישית להדמיה גיאוגרפית משופרת",aspectRatios:"צור סרטוני אנימציית טיול בפורמטים אנכי (9:16), מסך רחב (16:9), קולנוע (2.35:1) או ריבוע (1:1) מושלמים לאינסטגרם, טיקטוק, יוטיוב ופלטפורמות חברתיות אחרות",tripSpeed:'שלוט במהירות אנימטור מסלול המסע בין מיקומים (עד 3500 קמ"ש) ליצירת סרטוני סיכום טיול דינמיים או רגועים',pauseDuration:"התאם את משך ההשהיה בכל מיקום (0.5-5 שניות) כדי להדגיש יעדים חשובים בסרטוני הדגשות הטיול שלך",locationLabels:"הצג תוויות עיר, אזור ו/או מדינה בסרטוני מפת הטיולים המונפשים שלך כדי לספק הקשר למסע שלך",pathDisplay:"החלף אם ברצונך להציג את כל נתיבי הטיולים הקודמים או רק את הטיול הנוכחי באנימציית מסלול הטיול שלך"}}},q={meta:e,header:t,hero:i,howItWorks:r,videoSection:o,features:s,videoIdeas:l,screenshots:a,appStore:n,faq:p,contact:d,cookieBanner:c,footer:u,cta:T,about:R};export{R as about,n as appStore,d as contact,c as cookieBanner,T as cta,q as default,p as faq,s as features,u as footer,t as header,i as hero,r as howItWorks,e as meta,a as screenshots,l as videoIdeas,o as videoSection};
